sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartInstance = null;
    var dadosGraficos = $scope.data.dadosGraficoPessoal || [];

    $scope.exibirGrafico = dadosGraficos.length > 0;

    function inicializarGrafico(listaDados) {
        if (!listaDados || listaDados.length === 0) {
            if (chartInstance) {
                chartInstance.destroy();
                chartInstance = null;
            }
            $scope.exibirGrafico = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGrafico = true;
        $scope.$applyAsync();

        var listaAnos = listaDados.map(function(item) { return item.ano; });
        var despesasPessoal = listaDados.map(function(item) { return item.valorDespesa; });
        var receitasRCL = listaDados.map(function(item) { return item.valorReceita; });

        var contexto = document.getElementById('graficoLimitePessoal').getContext('2d');

        if (chartInstance) {
            chartInstance.destroy();
        }

        chartInstance = new Chart(contexto, {
            type: 'bar',
            data: {
                labels: listaAnos,
                datasets: [
                    {
                        label: 'Despesa Líquida com Pessoal',
                        data: despesasPessoal,
                        backgroundColor: '#4052D6',
                        yAxisID: 'eixoEsquerdo'
                    },
                    {
                        label: 'Receita Corrente Líquida - RCL - Para Fins de % Pessoal',
                        data: receitasRCL,
                        backgroundColor: '#60E1EB',
                        yAxisID: 'eixoEsquerdo'
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                layout: {
                    padding: {
                        left: 20,
                        right: 20
                    }
                },
                scales: {
                    x: {
                        title: { display: true, text: 'Ano' },
                        offset: true
                    },
                    eixoEsquerdo: {
                        type: 'linear',
                        position: 'left',
                        beginAtZero: true,
                        title: { display: true, text: 'Valores em Milhões (R$)' },
                        ticks: {
                            padding: 15,
                            callback: function(value) {
                                return value.toLocaleString('pt-BR') + ' mi';
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        position: 'top'
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': ' + context.parsed.y.toLocaleString('pt-BR') + ' mi';
                            }
                        }
                    }
                }
            }
        });
    }

    function obterDadosPorAno(ano) {
        if (!ano) {
            return dadosGraficos;
        }
        return dadosGraficos.filter(function(item) {
            return item.ano == ano;
        });
    }

    $rootScope.$on('anoSelecionado', function(evento, anoSelecionado) {
        var dadosFiltrados = obterDadosPorAno(anoSelecionado);
        inicializarGrafico(dadosFiltrados);
    });

    $timeout(function() {
        inicializarGrafico(obterDadosPorAno(null));
    }, 300);
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div {
 font-family: 'Roboto Flex', sans-serif;
}

sp_widget.script:
(function() {
    var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');
    gr.addQuery('u_ano', '>=', 2019);
    gr.addQuery('u_ano', '<=', 2024);
    gr.orderBy('u_ano');
    gr.query();

    var listaDados = [];
    while (gr.next()) {
        listaDados.push({
            ano: gr.getValue('u_ano'),
            valorDespesa: parseFloat(gr.getValue('u_despesa_liquida_pedidos')) / 1000000,
            valorReceita: parseFloat(gr.getValue('u_receita_corrente_liquida')) / 1000000,
            percentualComprometimento: parseFloat(gr.getValue('u_comprometimento_rcl')) || 0
        });
    }

    data.dadosGraficoPessoal = listaDados;
})();
